const listeningQuestionAudio={audio:null,button:null,examId:null,index:-1,start:0,end:0,rate:1,loop:false,timer:null,progress:null,token:0};
const manualListeningStoreKey='tcf-listening-manual-segments-v2';
let manualListeningSegments=(()=>{try{return JSON.parse(localStorage.getItem(manualListeningStoreKey)||'{}')||{}}catch(e){return{}}})();
const manualListeningDrafts={};
function listeningAudioKey(exam){return String(exam?.audio||'').split('/').pop()}
function baseListeningSegment(exam,index){const rows=LISTENING_SEGMENTS[listeningAudioKey(exam)]||[];const row=rows[index];if(!(row&&row.length===2))return null;const start=Math.max(0,+row[0]||0),end=Math.max(start+.01,+row[1]||0);return {start,end,sourceStart:start,sourceEnd:end,src:exam.audio}}
function manualListeningKey(exam,index){return `${listeningAudioKey(exam)}::${index}`}
function savedManualListeningSegment(exam,index){const item=manualListeningSegments[manualListeningKey(exam,index)];if(!item)return null;const start=Math.max(0,Number(item.start)||0),end=Math.max(start+.25,Number(item.end)||0);return {start,end,sourceStart:start,sourceEnd:end,src:exam.audio,manual:true}}
function listeningSegment(exam,index){return savedManualListeningSegment(exam,index)||baseListeningSegment(exam,index)}
function editableListeningSegment(exam,index){const key=manualListeningKey(exam,index),draft=manualListeningDrafts[key];if(draft){const start=Math.max(0,Number(draft.start)||0),end=Math.max(start+.25,Number(draft.end)||0);return {start,end,sourceStart:start,sourceEnd:end,src:exam.audio,manual:true,draft:true}}return listeningSegment(exam,index)}
function setManualListeningDraft(exam,index,start,end){const key=manualListeningKey(exam,index);start=Math.max(0,Number(start)||0);end=Math.max(start+1,Number(end)||start+1);manualListeningDrafts[key]={start:Math.round(start*1000)/1000,end:Math.round(end*1000)/1000};return editableListeningSegment(exam,index)}
function saveManualListeningDraft(exam,index){const key=manualListeningKey(exam,index),seg=editableListeningSegment(exam,index);if(!seg)return false;manualListeningSegments[key]={start:seg.start,end:seg.end};try{localStorage.setItem(manualListeningStoreKey,JSON.stringify(manualListeningSegments))}catch(e){};delete manualListeningDrafts[key];return true}
function resetManualListeningSegment(exam,index){const key=manualListeningKey(exam,index);delete manualListeningDrafts[key];delete manualListeningSegments[key];try{localStorage.setItem(manualListeningStoreKey,JSON.stringify(manualListeningSegments))}catch(e){};return baseListeningSegment(exam,index)}
function manualListeningDirty(exam,index){return !!manualListeningDrafts[manualListeningKey(exam,index)]}
function manualListeningSaved(exam,index){return !!manualListeningSegments[manualListeningKey(exam,index)]}
function fmtAudioTime(sec){sec=Math.max(0,Number(sec)||0);const m=Math.floor(sec/60),ss=Math.floor(sec%60);return `${m}:${String(ss).padStart(2,'0')}`}
