    if(speakingCorrectionAudio.paused){speakingCorrectionAudio.paused=false;button.textContent='⏸ Pause';try{synth.resume()}catch(e){};if(!synth.speaking)speakNextCorrectionChunk(speakingCorrectionAudio.token)}
    else{speakingCorrectionAudio.paused=true;button.textContent='▶ Resume';try{synth.pause()}catch(e){}}
