const LEVEL_BANDS={B1:{start:10,end:18,label:'B1',range:'Q11–19'},B2:{start:19,end:28,label:'B2',range:'Q20–29'},C1:{start:29,end:34,label:'C1',range:'Q30–35'},C2:{start:35,end:38,label:'C2',range:'Q36–39'}};
