function questionsForLevels(levels){const set=new Set(levels);return Array.from({length:39},(_,i)=>i).filter(i=>set.has(levelForQuestion(i)))}
function levelReviewCount(e,scope,levels){const per=questionsForLevels(levels).length;return scope==='all'?exams.filter(x=>x.type===e.type).length*per:per}
function levelReviewControls(e){return `<div class="level-review-card"><div class="level-review-kicker">Practice only</div><h4>Level review</h4><p>Review selected B1–C2 questions without changing Exam Mode.</p><div class="level-review-label">Scope</div><div class="level-review-scope"><button type="button" class="lr-toggle active" data-lr-scope="single">This test</button><button type="button" class="lr-toggle" data-lr-scope="all">All ${e.type==='listening'?'Listening':'Reading'}</button></div><div class="level-review-label">Levels</div><div class="level-review-levels">${LEVEL_ORDER.map(k=>`<button type="button" class="lr-level active" data-lr-level="${k}" aria-pressed="true"><b>${k}</b><span>${LEVEL_BANDS[k].range}</span></button>`).join('')}</div><div class="level-review-summary" data-lr-summary></div><button type="button" class="btn level-review-start" data-lr-start>Start selected review</button></div>`}
function bindLevelReviewControls(e){let scope='single';const scopeBtns=[...document.querySelectorAll('[data-lr-scope]')],levelBtns=[...document.querySelectorAll('[data-lr-level]')],summary=$('[data-lr-summary]');const selectedLevels=()=>levelBtns.filter(b=>b.classList.contains('active')).map(b=>b.dataset.lrLevel);const update=()=>{const levels=selectedLevels(),count=levelReviewCount(e,scope,levels);scopeBtns.forEach(b=>b.classList.toggle('active',b.dataset.lrScope===scope));if(summary)summary.innerHTML=levels.length?`<b>${count}</b> question${count===1?'':'s'} · ${levels.join(' + ')}`:'Select at least one level';const start=$('[data-lr-start]');if(start)start.disabled=!levels.length};scopeBtns.forEach(b=>b.onclick=()=>{scope=b.dataset.lrScope;update()});levelBtns.forEach(b=>b.onclick=()=>{b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active')?'true':'false');update()});const start=$('[data-lr-start]');if(start)start.onclick=()=>startLevelReview(e.id,scope,selectedLevels());update()}
