    const skillName = skill === 'listening' ? 'Listening' : 'Reading';
    const stats = lpStats(lpRun.practiceRecord);
    const completed = lpRun.refs.length;
    lpRun.refs.forEach(ref => lpUpdateMistake(ref, {
      lastPractisedAt: new Date().toISOString(),
      practiceCount: (lpGetMistakeBank(skill).find(item => item.key === ref.mistakeKey)?.practiceCount || 0) + 1
    }));
    stopQuestionAudio();
    $('#app').innerHTML = shell(`<section class="panel lp-complete"><div class="lp-complete-icon">📚</div><div class="eyebrow">Mistake revision complete</div><h1>${skillName} · Mistake Bank</h1><p>You revised ${completed} saved mistake${completed === 1 ? '' : 's'}. Your original first-attempt records are still safely saved.</p><div class="lp-complete-stats"><span><b>${stats.correct}</b>Correct in revision</span><span><b>${stats.incorrect}</b>Incorrect in revision</span><span><b>${completed}</b>Questions revised</span></div><div class="lp-card-actions" style="justify-content:center"><button class="btn btn-primary" data-lp-bank-back>Back to Mistake Bank</button><button class="btn btn-ghost" data-lp-library>Back to main library</button></div></section>`);
    lpBindLibraryButtons();
    const backToBank = $('[data-lp-bank-back]');
    if (backToBank) backToBank.onclick = () => lpRenderMistakeBank(skill);
